//! Cross-validation of the Rust GenomicSEM port against R lavaan golden
//! outputs (generated by `tests/fixtures-gen/gen_golden.R`).
//!
//! These tests load JSON fixtures containing:
//! - Known S (genetic covariance) and V (sampling covariance) matrices
//! - R lavaan parameter estimates from `sem()` with DWLS estimation
//! - GenomicSEM sandwich SEs computed from lavaan's delta/WLS.V
//! - Model chi-square from the eigen-decomposition formula
//!
//! The Rust SEM engine is run on the same S/V inputs and compared to the
//! R golden values within tolerance.
//!
//! Point estimates (loadings, variances) should match to ~1e-2 relative;
//! sandwich SEs match to ~5e-2 relative (sensitive to numerical Jacobian).

use std::fs;

use faer::Mat;
use serde::Deserialize;
use serde_json::Value;

use genomic_sem::*;

const GOLDEN_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/golden");

// ── Helpers ──────────────────────────────────────────────────────────────

fn load_json(name: &str) -> Value {
    let path = format!("{GOLDEN_DIR}/{name}");
    let s = fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path));
    serde_json::from_str(&s).unwrap_or_else(|e| panic!("parse JSON {}: {e}", path))
}

/// Parse a JSON 2D array into a faer Mat<f64>.
fn json_to_mat(v: &Value) -> Mat<f64> {
    let rows = v.as_array().expect("expected 2D array");
    let n = rows.len();
    let m = rows[0].as_array().expect("row is array").len();
    let mut mat = Mat::zeros(n, m);
    for i in 0..n {
        let row = rows[i].as_array().unwrap();
        for j in 0..m {
            mat[(i, j)] = row[j].as_f64().unwrap();
        }
    }
    mat
}

/// Parse a JSON 1D array into Vec<f64>.
fn json_to_vec(v: &Value) -> Vec<f64> {
    v.as_array()
        .expect("expected 1D array")
        .iter()
        .map(|x| x.as_f64().unwrap_or(f64::NAN))
        .collect()
}

/// Relative tolerance check: |a - b| <= rel * max(|b|, abs) + abs.
fn close(a: f64, b: f64, rel: f64, abs: f64) -> bool {
    if a.is_nan() && b.is_nan() {
        return true;
    }
    if a.is_nan() || b.is_nan() {
        return false;
    }
    (a - b).abs() <= rel * b.abs().max(1e-12) + abs
}

/// Build a Covstruc from the JSON scenario.
fn scenario_to_covstruc(scen: &Value) -> utils::Covstruc {
    let s = json_to_mat(&scen["S"]);
    let k = s.nrows();
    let z = k * (k + 1) / 2;
    let v_diag = json_to_vec(&scen["V_diag"]);
    let v = linalg::diag_from_vec(&v_diag);

    utils::Covstruc {
        v,
        s,
        i_mat: Mat::<f64>::identity(k, k),
        n: Mat::zeros(1, z),
        m: 100_000.0,
        v_stand: None,
        s_stand: None,
    }
}

/// Extract the lavaan golden parameter estimates for free parameters only.
struct GoldenParams {
    lhs: Vec<String>,
    op: Vec<String>,
    rhs: Vec<String>,
    est: Vec<f64>,
    se: Vec<f64>,
}

fn golden_params(scen: &Value) -> GoldenParams {
    let lhs: Vec<String> = scen["par_lhs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let op: Vec<String> = scen["par_op"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let rhs: Vec<String> = scen["par_rhs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let free: Vec<i64> = scen["par_free"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_i64().unwrap())
        .collect();
    let est_all = json_to_vec(&scen["par_est"]);
    let se_all = json_to_vec(&scen["sandwich_SE"]);

    // Keep only free parameters (free > 0), in order of free index
    let mut indices: Vec<usize> = (0..free.len()).filter(|&i| free[i] > 0).collect();
    indices.sort_by_key(|&i| free[i]);

    // sandwich_SE is indexed by free-parameter position (0-based), not by
    // table row. Map each table index to its SE position: free_idx - 1.
    GoldenParams {
        lhs: indices.iter().map(|&i| lhs[i].clone()).collect(),
        op: indices.iter().map(|&i| op[i].clone()).collect(),
        rhs: indices.iter().map(|&i| rhs[i].clone()).collect(),
        est: indices.iter().map(|&i| est_all[i]).collect(),
        se: indices
            .iter()
            .map(|&i| {
                let se_idx = (free[i] - 1) as usize;
                if se_idx < se_all.len() {
                    se_all[se_idx]
                } else {
                    f64::NAN
                }
            })
            .collect(),
    }
}

// =====================================================================
// Scenario 1: 3-trait saturated one-factor
// =====================================================================

#[test]
fn xval_scenario1_parameter_recovery() {
    let scen = load_json("scenario1_one_factor_3trait.json");
    let covstruc = scenario_to_covstruc(&scen);

    // Run Rust SEM
    let config = usermodel::UserModelConfig {
        model: scen["model"].as_str().unwrap().to_string(),
        ..Default::default()
    };
    let result = usermodel::usermodel(&covstruc, &config).unwrap();

    // The model is saturated (df=0), so loadings should be recovered exactly.
    // Compare each loading against the known true values.
    let loading_results: Vec<&usermodel::ParamResult> =
        result.results.iter().filter(|r| r.op == "=~").collect();
    assert_eq!(loading_results.len(), 3, "Expected 3 factor loadings");

    let true_loadings = json_to_vec(&scen["true_loadings"]);
    for (i, r) in loading_results.iter().enumerate() {
        // Exact match expected for saturated model: machine precision
        assert!(
            close(r.unstand_est, true_loadings[i], 1e-6, 1e-8),
            "Loading {}: Rust={:.10} vs true={:.10}",
            i,
            r.unstand_est,
            true_loadings[i]
        );
    }

    // Compare model-implied covariance against lavaan's: machine precision
    let golden_implied = json_to_mat(&scen["implied"]);
    for i in 0..3 {
        for j in 0..3 {
            assert!(
                close(
                    result.sem_implied[(i, j)],
                    golden_implied[(i, j)],
                    1e-6,
                    1e-9
                ),
                "Implied[{},{}]: Rust={:.10} vs lavaan={:.10}",
                i,
                j,
                result.sem_implied[(i, j)],
                golden_implied[(i, j)]
            );
        }
    }
}

#[test]
fn xval_scenario1_chisq() {
    let scen = load_json("scenario1_one_factor_3trait.json");
    let golden_chisq = scen["chisq"].as_f64().unwrap();

    // For a saturated model, chi-square should be ~0
    assert!(
        golden_chisq.abs() < 1e-10,
        "Golden chi-sq: {}",
        golden_chisq
    );
}

#[test]
fn xval_scenario1_df() {
    let scen = load_json("scenario1_one_factor_3trait.json");
    let golden_df = scen["df"].as_i64().unwrap();
    assert_eq!(golden_df, 0, "3-trait one-factor = saturated (df=0)");
}

