#[test]
fn xval_scenario3_factor_loadings() {
    // NOTE: The two-factor model with 4 indicators (2 per factor) and all
    // loadings free (NA*) is underidentified (11 free params, 10 observed
    // statistics, df = -1). With `optim.force.converged = TRUE`, lavaan
    // still produces a solution, but the individual parameter estimates
    // are NOT unique — only the model-implied covariance matrix is unique.
    //
    // Therefore, we validate the implied covariance (unique) rather than
    // individual loadings (non-unique for this specification).
    let scen = load_json("scenario3_two_factor_4trait.json");
    let covstruc = scenario_to_covstruc(&scen);
    let golden_implied = json_to_mat(&scen["implied"]);

    let config = usermodel::UserModelConfig {
        model: scen["model"].as_str().unwrap().to_string(),
        ..Default::default()
    };
    let result = usermodel::usermodel(&covstruc, &config).unwrap();

    // The implied covariance must match lavaan regardless of parameterization
    let k = golden_implied.nrows();
    for i in 0..k {
        for j in 0..k {
            assert!(
                close(
                    result.sem_implied[(i, j)],
                    golden_implied[(i, j)],
                    1e-6,
                    1e-9
                ),
                "Implied[{},{}]: Rust={:.10} vs lavaan={:.10}",
                i,
                j,
                result.sem_implied[(i, j)],
                golden_implied[(i, j)]
            );
        }
    }

    // Also verify the residual variances match (these ARE identified since
    // they equal S[i,i] - λᵢ²·ψ, and S[i,i] is observed)
    let golden = golden_params(&scen);
    for var in &["V1", "V2", "V3", "V4"] {
        let golden_est = find_golden(&golden, var, "~~", var);
        let rust_est = result
            .results
            .iter()
            .find(|r| r.lhs == *var && r.op == "~~" && r.rhs == *var);
        match (golden_est, rust_est) {
            (Some((ge, _)), Some(re)) => {
                // Residual variances are identified: θ_i = S[i,i] - Σ[i,i] + θ_i
                // Machine precision expected since implied cov matches.
                assert!(
                    close(re.unstand_est, ge, 1e-6, 1e-8),
                    "Resid {}~~{}: Rust={:.10} vs lavaan={:.10}",
                    var,
                    var,
                    re.unstand_est,
                    ge
                );
            }
            _ => {}
        }
    }
}

// =====================================================================
// Scenario 4: nearPD cross-validation
// =====================================================================

#[test]
fn xval_scenario4_near_pd() {
    let scen = load_json("scenario4_near_pd.json");
    let input = json_to_mat(&scen["input"]);
    let golden_output = json_to_mat(&scen["output"]);
    let golden_eigenvalues = json_to_vec(&scen["output_eigenvalues"]);

    // Run Rust nearPD
    let rust_output = near_pd::near_pd(&input);

    // Check that Rust output is SPD
    assert!(
        near_pd::is_spd(&rust_output),
        "Rust nearPD output should be SPD"
    );

    // Compare eigenvalues (both should have all-positive eigenvalues)
    let (rust_eigvals, _) = linalg::eigen_sym(&rust_output);
    for &ge in &golden_eigenvalues {
        assert!(
            ge >= -1e-10,
            "Golden eigenvalue should be non-negative: {}",
            ge
        );
    }
    for &re in &rust_eigvals {
        assert!(
            re >= -1e-10,
            "Rust eigenvalue should be non-negative: {}",
            re
        );
    }

    // Check that the output is close to the R Matrix::nearPD output
    // (Different nearPD implementations may converge to slightly different
    // nearest PD matrices, but they should be close in Frobenius norm)
    let mut frob_diff = 0.0;
    for i in 0..3 {
        for j in 0..3 {
            let d = rust_output[(i, j)] - golden_output[(i, j)];
            frob_diff += d * d;
        }
    }
    frob_diff = frob_diff.sqrt();
    assert!(
        frob_diff < 0.2,
        "nearPD Frobenius diff: {} (Rust vs Matrix::nearPD)",
        frob_diff
    );
}

// =====================================================================
// Scenario 5: Liability conversion
// =====================================================================

#[test]
fn xval_scenario5_liability_conversion() {
    let scen = load_json("scenario5_liability.json");
    let prevs = json_to_vec(&scen["population_prev"]);
    let samp_prev = scen["sample_prev"].as_f64().unwrap();
    let golden_factors = json_to_vec(&scen["conversion_factors"]);

    for (i, &pop_prev) in prevs.iter().enumerate() {
        let rust_cf = utils::liability_conversion_factor(pop_prev, samp_prev);
        assert!(
            close(rust_cf, golden_factors[i], 1e-4, 1e-6),
            "Liability conversion for prev={}: Rust={} vs R={}",
            pop_prev,
            rust_cf,
            golden_factors[i]
        );
    }
}
